import{_ as e,c as l,o,a7 as a}from"./chunks/framework.DNE_2Uup.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"basic/htmlcssjs/html/index.md","filePath":"basic/htmlcssjs/html/index.md","lastUpdated":1745417180000}'),i={name:"basic/htmlcssjs/html/index.md"};function d(c,t,r,s,n,p){return o(),l("div",null,t[0]||(t[0]=[a('<h3 id="html-概括" tabindex="-1">HTML 概括 <a class="header-anchor" href="#html-概括" aria-label="Permalink to &quot;HTML 概括&quot;">​</a></h3><p><strong>HTML（HyperText Markup Language，超文本标记语言）</strong> 是用于创建网页的标准标记语言。它是网页开发的基础技术，定义了网页的结构和内容。</p><h3 id="功能与作用" tabindex="-1">功能与作用 <a class="header-anchor" href="#功能与作用" aria-label="Permalink to &quot;功能与作用&quot;">​</a></h3><ol><li><p><strong>结构化内容</strong></p><ul><li>HTML 通过标签（如 <code>&lt;h1&gt;</code>, <code>&lt;p&gt;</code>, <code>&lt;div&gt;</code> 等）定义网页中的标题、段落、链接、图像等元素，使内容具有结构化特性。</li></ul></li><li><p><strong>超链接功能</strong></p><ul><li>使用 <code>&lt;a&gt;</code> 标签实现不同网页之间的链接，构建互联的网络环境。</li></ul></li><li><p><strong>多媒体支持</strong></p><ul><li>提供插入图片、音频、视频等功能，丰富网页的表现形式（如 <code>&lt;img&gt;</code>, <code>&lt;audio&gt;</code>, <code>&lt;video&gt;</code> 标签）。</li></ul></li><li><p><strong>表单交互</strong></p><ul><li>支持表单元素（如 <code>&lt;input&gt;</code>, <code>&lt;button&gt;</code>, <code>&lt;textarea&gt;</code>），实现用户输入和数据提交功能。</li></ul></li><li><p><strong>语义化表达</strong></p><ul><li>使用语义化标签（如 <code>&lt;header&gt;</code>, <code>&lt;footer&gt;</code>, <code>&lt;article&gt;</code>）描述网页内容的意义，便于搜索引擎和辅助设备理解。</li></ul></li><li><p><strong>基础框架</strong></p><ul><li>为 CSS（样式设计）和 JavaScript（动态交互）提供载体，三者共同构建现代网页。</li></ul></li></ol><p>总结来说，HTML 是网页开发的核心语言，负责定义内容的结构和意义，是构建网页的基础。</p>',5)]))}const h=e(i,[["render",d]]);export{u as __pageData,h as default};
